const t=String.raw;
export const quantumData:QuantumLessonData[]=[
{id:'photoeffekt',title:'Photoeffekt: Licht überträgt Energie in Quanten',lead:'Bestimme aus einer Gegenspannung die maximale Elektronenenergie und unterscheide Lichtfrequenz von Intensität.',word:'Die',hook:'Warum löst helles rotes Licht nicht dieselben Elektronen aus wie schwaches UV-Licht?',application:'Photoelektrische Detektoren setzen einzelne Absorptionsereignisse in elektrische Signale um. Die Energie eines Photons entscheidet, welche Prozesse möglich sind; die Zahl der Photonen beeinflusst dagegen die Ereignisrate.',model:'photo',
 experiments:[{title:'Lehrerversuch · Photozelle mit Gegenfeld',kind:'photo',materials:'Zugelassener Photoeffekt-Schulapparat mit eingebauten Lichtquellen bekannter Frequenz, Photozelle, empfindlicher Strommessung und regelbarer Gegenspannung. Aufbau und abgeschirmte UV-Quellen ausschließlich nach Geräteanleitung durch die Lehrkraft.',
 steps:['Skizziere Quelle, beleuchtete Kathode, Auffänger und Gegenfeld. Vermute getrennt, was höhere Frequenz und höhere Intensität bewirken.', 'Lasse für eine Lichtfarbe die Gegenspannung erhöhen, bis der Photostrom gerade verschwindet. Notiere den Betrag im Heft.', 'Wiederhole bei mehreren Frequenzen und anschließend bei derselben Frequenz mit zwei Intensitäten. Kontrolliere Dunkelstrom und Geräte-Nullpunkt.'],
 columns:[t`Lichtfrequenz $f$ in $\mathrm{THz}$`,t`Betrag der Gegenspannung $U_{\mathrm g}$ in $\mathrm V$`],rows:[['500','0,068'],['600','0,482'],['700','0,895'],['800','1,309']],
 note:t`Didaktische Modellwerte für die frei gewählte Austrittsarbeit $W_{\mathrm A}=2{,}00\,\mathrm{eV}$ und $h=4{,}136\cdot10^{-15}\,\mathrm{eV\,s}$. Keine behaupteten Messwerte einer bestimmten Kathode; Kontaktpotentiale sind nicht enthalten.`,
 task:t`Zeichne $U_{\mathrm g}$ gegen $f$ mit den ausgeschriebenen Tabellenbezeichnungen an den Achsen. Bestimme Steigung, Grenzfrequenz und Austrittsarbeit. Halte die Intensitätsbeobachtung als eigenen Vergleich fest.`,
 solution:t`Die Steigung beträgt ungefähr $0{,}004136\,\frac{\mathrm V}{\mathrm{THz}}$. Daher $\frac he\approx4{,}136\cdot10^{-15}\,\mathrm{V\,s}$. Der extrapolierte Achsenabschnitt ist $-2{,}00\,\mathrm V$, die Grenzfrequenz etwa $484\,\mathrm{THz}$. Daraus folgt $W_{\mathrm A}=2{,}00\,\mathrm{eV}$.`,
 interpretation:'Im einfachen Einphotonenmodell erhöht mehr Intensität oberhalb der Schwelle die Zahl ausgelöster Elektronen, nicht deren maximale kinetische Energie. Unterhalb der Schwelle entsteht dadurch kein Einphotonen-Photoeffekt. Sehr starke Mehrphotonenprozesse gehören nicht zu diesem Modell.'}],
 theory:[t`Ein Photon der Frequenz $f$ trägt $E_{\mathrm{Ph}}=hf$. Beim äußeren Photoeffekt muss zunächst die Austrittsarbeit überwunden werden. Der Rest kann als kinetische Energie des Elektrons erscheinen; Elektronen aus tieferen Zuständen können weniger Energie besitzen.`,t`Die Gegenspannung bremst auch die schnellsten Photoelektronen gerade ab: $eU_{\mathrm g}=E_{\mathrm{kin,max}}$. Unterhalb $f_{\mathrm g}=\frac{W_{\mathrm A}}h$ gibt es im Einphotonenmodell keine Emission. Negative rechnerische Restenergie bedeutet deshalb nicht negative Bewegungsenergie.`,t`Licht zeigt in anderen Experimenten Interferenz. Die Photonbeschreibung ersetzt diese Welleneigenschaften nicht durch ein Bild klassischer kleiner Kugeln. Benutze für Rechnungen $e=1{,}602\cdot10^{-19}\,\mathrm C$ und $hc\approx1240\,\mathrm{eV\,nm}$.`],
 formulas:[t`E_{\mathrm{Ph}}=hf=\frac{hc}{\lambda}`,t`E_{\mathrm{kin,max}}=hf-W_{\mathrm A}=eU_{\mathrm g}`],memory:'Die Frequenz bestimmt die Energie pro Photon. Die Intensität bestimmt bei gleicher Frequenz wesentlich, wie viele Photonen pro Zeit und Fläche ankommen.',
 exercises:[{title:'Grundlagen · Eine Kathode beurteilen',task:t`Licht mit $\lambda=400\,\mathrm{nm}$ trifft auf $W_{\mathrm A}=2{,}00\,\mathrm{eV}$. Bestimme Photonenenergie und Gegenspannung.` ,solution:t`$E_{\mathrm{Ph}}=\frac{1240}{400}\,\mathrm{eV}=3{,}10\,\mathrm{eV}$. Somit $E_{\mathrm{kin,max}}=1{,}10\,\mathrm{eV}$ und $U_{\mathrm g}=1{,}10\,\mathrm V$.`,interpretation:'Die Elektronen erhalten nur die nach dem Austritt verbleibende Energie.'},{title:'Anwendung · Detektorrate erhöhen',task:t`Eine Quelle liefert bei $E_{\mathrm{Ph}}=3{,}0\,\mathrm{eV}$ eine Leistung von $P=1{,}0\,\mathrm{\mu W}$. Schätze die Photonenzahl pro Sekunde. Warum ist der gemessene Elektronenstrom ohne weitere Angaben nicht festgelegt?`,solution:t`$\dot N=\frac P{E_{\mathrm{Ph}}}\approx\frac{10^{-6}}{3{,}0\cdot1{,}602\cdot10^{-19}}\,\mathrm{s^{-1}}=2{,}08\cdot10^{12}\,\mathrm{s^{-1}}$. Absorption, beleuchtete Fläche, Quantenausbeute und Sammlung der Elektronen beeinflussen den Strom.`,interpretation:'Eine Photonenzahl ist noch keine Zahl tatsächlich registrierter Elektronen.'}]},
{id:'photonenimpuls',title:'Photonenimpuls und Compton-Streuung',lead:'Verbinde Photonenenergie mit Impuls und erkläre, weshalb gestreute Röntgenphotonen längerwellig werden können.',word:'Quantenphysik',hook:'Wie kann Licht einen Impuls übertragen, obwohl Photonen keine Ruhemasse besitzen?',application:'Lichtdruck überträgt Impuls auf Oberflächen. Bei der Compton-Streuung lässt sich der Impulsübertrag eines Photons auf ein Elektron besonders deutlich aus der geänderten Wellenlänge erschließen.',
 experiments:[{title:'Historisches Experiment auswerten · Compton-Streuung',kind:'compton',materials:'Prinzipskizze und Ersatzdaten. Der historische Aufbau verwendet Röntgenquelle, Streukörper und winkelabhängige Spektrometrie. Hier findet kein Aufbau einer Strahlenquelle statt; ein vorhandener zugelassener Schulapparat darf nur von der befugten Lehrkraft betrieben werden.',
 steps:['Zeichne einfallendes Photon, Streuwinkel und Richtung des Rückstoßelektrons. Unterscheide gestreutes Licht und Materieteilchen.','Vergleiche die Photonenwellenlänge bei verschiedenen Winkeln. Notiere Ausgangswellenlänge und Streuwinkel im Heft.','Berechne die Änderung und prüfe, ob sie bei gleichem Winkel vom frei gewählten Ausgangswert abhängen würde.'],
 columns:[t`Photonen-Streuwinkel $\theta$ in $\mathrm{Grad}$`,t`Gestreute Wellenlänge $\lambda'$ in $\mathrm{pm}$`],rows:[['0','20,000'],['30','20,325'],['60','21,213'],['90','22,426'],['120','23,639'],['180','24,852']],
 note:t`Berechnete Modellwerte für $\lambda=20{,}000\,\mathrm{pm}$ und $\lambda_{\mathrm C}=2{,}426\,\mathrm{pm}$; freies, anfangs ruhendes Elektron. Keine Originaldaten Comptons.`,
 task:t`Ergänze $\Delta\lambda=\lambda'-\lambda$ im Heft. Zeichne $\Delta\lambda$ in $\mathrm{pm}$ gegen $1-\cos\theta$ in $1$ und bestimme die Steigung. Berechne bei $90^\circ$ Anfangs- und Endenergie des Photons.`,
 solution:t`Die Steigung ist $2{,}426\,\mathrm{pm}$. Bei $90^\circ$ sinkt die Photonenenergie von $62{,}0\,\mathrm{keV}$ auf etwa $55{,}3\,\mathrm{keV}$. Etwa $6{,}7\,\mathrm{keV}$ werden auf das Elektron übertragen.`,
 interpretation:'Die Energie des Gesamtsystems bleibt erhalten. Für gebundene Elektronen und reale Streukörper treten weitere Beiträge auf; auch ein unverschobener Anteil ist möglich. Das freie Elektron ist eine gezielte Modellannahme.'}],
 theory:[t`Ein Photon besitzt Energie und Impuls, aber keine Ruhemasse. Es gilt $p=\frac Ec=\frac h\lambda$. Deshalb muss beim Streuprozess neben der Energie auch der gerichtete Impuls bilanziert werden.`,t`Die gleichzeitige relativistische Energie- und Impulserhaltung für ein anfangs ruhendes freies Elektron ergibt $\Delta\lambda=\frac h{m_{\mathrm e}c}(1-\cos\theta)$. Der Photonenwinkel legt die Verschiebung fest. Die Energieübertragung ist nicht für jeden Winkel gleich.`,t`Diese Formel ist kein klassischer elastischer Billardstoß. Das Elektron erhält kinetische Energie, das Photon bleibt ein Photon mit kleinerer Energie. Bei vollständiger Absorption an einer Oberfläche wird dessen Impuls übertragen; Reflexion kann den Normalimpuls stärker ändern.`],
 formulas:[t`p_{\mathrm{Ph}}=\frac{E_{\mathrm{Ph}}}{c}=\frac h\lambda`,t`\Delta\lambda=\lambda_{\mathrm C}(1-\cos\theta),\qquad\lambda_{\mathrm C}=\frac h{m_{\mathrm e}c}`],memory:'Photonen übertragen Energie und Impuls. Bei Compton-Streuung an einem anfangs ruhenden freien Elektron wird die Photonenwellenlänge um einen winkelabhängigen Betrag größer.',
 exercises:[{title:'Grundlagen · Impuls eines sichtbaren Photons',task:t`Berechne den Impuls bei $\lambda=500\,\mathrm{nm}$ mit $h=6{,}626\cdot10^{-34}\,\mathrm{J\,s}$. Wie groß ist der Impulsübertrag bei senkrechter idealer Rückreflexion?`,solution:t`$p=\frac h\lambda=1{,}33\cdot10^{-27}\,\frac{\mathrm{kg\,m}}{\mathrm s}$. Der Spiegel erhält bei Umkehr des Photonenimpulses den Betrag $2p=2{,}65\cdot10^{-27}\,\frac{\mathrm{kg\,m}}{\mathrm s}$.`,interpretation:'Impuls ist gerichtet: Gleiche Energie vor und nach der idealen Reflexion bedeutet nicht unveränderten Impuls.'},{title:'Anwendung · Winkel aus der Verschiebung',task:t`Bei einer Compton-Messung ist $\Delta\lambda=1{,}213\,\mathrm{pm}$. Bestimme den Photonen-Streuwinkel. Kann die Verschiebung in diesem Modell $6{,}0\,\mathrm{pm}$ betragen?`,solution:t`$1-\cos\theta=\frac{1{,}213}{2{,}426}=\frac12$, also $\theta=60^\circ$. Maximal möglich ist $2\lambda_{\mathrm C}=4{,}852\,\mathrm{pm}$; $6{,}0\,\mathrm{pm}$ passt nicht zu diesem Einzelstreumodell.`,interpretation:'Ein unpassender Wert verlangt eine Prüfung von Messung und Modellbedingungen, keine negative oder unmögliche Kosinuslösung.'}]},
{id:'materiewellen',title:'Materiewellen und Elektronenbeugung',lead:'Berechne die de-Broglie-Wellenlänge und erschließe aus Beugungsringen die Struktur eines Kristalls.',word:'beschreibt',hook:'Warum können Elektronen ein Beugungsbild erzeugen?',application:'Elektronenmikroskope nutzen die sehr kleine de-Broglie-Wellenlänge schneller Elektronen. Das ermöglicht prinzipiell feine räumliche Auflösung; tatsächliche Geräte werden zusätzlich durch Linsenfehler, Probenpräparation und Wechselwirkungen begrenzt.',
 experiments:[{title:'Lehrerversuch · Elektronenbeugung an Graphit',kind:'diffraction',materials:'Geschlossene zugelassene Elektronenbeugungsröhre mit Graphitfolie und vorgesehener Versorgung. Bedienung ausschließlich durch die Lehrkraft; Hochspannungsanschlüsse bleiben geschützt. Alternativ werden die Ersatzdaten ausgewertet.',
 steps:['Skizziere Elektronenquelle, Beschleunigungsbereich, Graphit und Leuchtschirm. Erkläre vorab, weshalb einzelne Auftreffereignisse zusammen Ringe bilden könnten.','Beobachte dieselbe Ringfamilie bei mehreren zulässigen Beschleunigungsspannungen. Miss jeweils den Durchmesser und protokolliere die Schirmgeometrie im Heft.','Prüfe getrennt, ob höheres Tempo größere oder kleinere Ringe erzeugt. Behalte stets denselben Ring und denselben Kristall-Netzebenenabstand bei.'],
 columns:[t`Beschleunigungsspannung $U$ in $\mathrm V$`,t`Ringdurchmesser $D_{\mathrm R}$ in $\mathrm{mm}$`],rows:[['2000','34,76'],['3000','28,38'],['4000','24,58'],['5000','21,99']],
 note:t`Berechnete Kleinwinkelwerte bei Schirmabstand $L=0{,}135\,\mathrm m$ und Netzebenenabstand $d=0{,}213\,\mathrm{nm}$: $D_{\mathrm R}\approx\frac{2L\lambda}{d}$. Nichtrelativistisches Elektronenmodell; gekrümmter Schirm und Geometriekorrekturen sind nicht berücksichtigt.`,
 task:t`Berechne zu jeder Spannung $\lambda$ und anschließend $d$ aus dem Ringdurchmesser. Zeichne $D_{\mathrm R}$ gegen $\frac1{\sqrt U}$ mit vollständigen Größen- und Einheitenangaben. Erkläre den Kurvenverlauf.`,
 solution:t`Die Wellenlängen betragen ungefähr $27{,}42;\,22{,}39;\,19{,}39;\,17{,}34\,\mathrm{pm}$. Jede Zeile liefert $d\approx0{,}213\,\mathrm{nm}$. Die lineare Abhängigkeit von $\frac1{\sqrt U}$ folgt aus der de-Broglie-Beziehung und der Beschleunigungsenergie.`,
 interpretation:'Die Ringe entstehen durch viele Kristallorientierungen in einer polykristallinen Probe. Der Streuwinkel ist doppelt so groß wie der Bragg-Winkel; eine Verwechslung führt zu einem Faktorfehler.'}],
 theory:[t`Materieteilchen mit Impuls $p$ besitzen die de-Broglie-Wellenlänge $\lambda=\frac hp$. Nichtrelativistisch gilt nach Beschleunigung eines Elektrons aus nahezu der Ruhe $eU=\frac12m_{\mathrm e}v^2$ und damit $\lambda=\frac h{\sqrt{2m_{\mathrm e}eU}}$.`,t`Am Kristall können die Wahrscheinlichkeitsamplituden verschiedener Streuwege interferieren. Die Bragg-Bedingung $2d\sin\theta=n\lambda$ beschreibt konstruktive Interferenz; der Winkel zwischen einfallendem und gestreutem Strahl ist $2\theta$.`,t`Ein Elektron ist keine kleine Kugel, auf deren Oberfläche eine materielle Wasserwelle sitzt. Die Wellenbeschreibung liefert Nachweiswahrscheinlichkeiten. Bei sehr hohen Beschleunigungsspannungen muss die nichtrelativistische Impuls-Energie-Beziehung ersetzt werden.`],
 formulas:[t`\lambda=\frac hp,\qquad \lambda_{\mathrm e}\approx\frac{1{,}2264\,\mathrm{nm}}{\sqrt{\frac U{\mathrm V}}}`,t`2d\sin\theta=n\lambda`],memory:'Je größer der Impuls, desto kleiner die de-Broglie-Wellenlänge. Beugung von Elektronen ist ein experimenteller Hinweis auf ihre quantenphysikalischen Welleneigenschaften.',
 exercises:[{title:'Grundlagen · Beschleunigung vervierfachen',task:t`Ein Elektron erhält statt $U=100\,\mathrm V$ nun $400\,\mathrm V$. Berechne beide Wellenlängen im nichtrelativistischen Modell.` ,solution:t`Bei $100\,\mathrm V$ gilt $\lambda\approx0{,}1226\,\mathrm{nm}$; bei $400\,\mathrm V$ etwa $0{,}0613\,\mathrm{nm}$. Die vierfache Spannung verdoppelt den Impuls und halbiert die Wellenlänge.` ,interpretation:'Wellenlänge und Beschleunigungsspannung sind nicht direkt umgekehrt proportional.'},{title:'Anwendung · Ringbild beurteilen',task:t`Der Durchmesser einer Ringfamilie sinkt von $40\,\mathrm{mm}$ auf $20\,\mathrm{mm}$. Um welchen Faktor muss die Spannung im verwendeten Modell steigen? Nenne eine Grenze der Schlussfolgerung.` ,solution:t`Aus $D_{\mathrm R}\propto U^{-\frac12}$ folgt die vierfache Spannung. Derselbe Ring, dieselbe Schirmgeometrie und die nichtrelativistische Kleinwinkelnäherung müssen weiterhin gelten.` ,interpretation:'Der Wechsel zu einem anderen Ring wäre keine gültige Spannungsmessung.'}]},
{id:'quanteninterferenz',title:'Einzelquanten am Doppelspalt: Zufall und Weginformation',lead:'Trenne einzelne lokale Nachweise vom statistischen Interferenzmuster und erkläre den Einfluss unterscheidbarer Wege.',word:'Materie',hook:'Wie entsteht ein Muster, wenn die Teilchen einzeln ankommen?',application:'Quanteninterferometer reagieren auf relative Phasen und werden für präzise Messungen genutzt. Ein einzelner Nachweis bleibt lokal; die statistische Verteilung vieler gleich präparierter Quanten enthält die Interferenzinformation.',model:'interference',
 experiments:[{title:'Forschungsexperiment auswerten · Einzelne Elektronen und Interferenz',kind:'double',materials:'Originalbeschreibung des Einzel-Elektronen-Interferenzexperiments von Tonomura und Mitarbeitern bei Hitachi sowie schematische Doppelspaltdarstellung. Das historische Experiment verwendete ein Elektronenbiprisma, nicht zwei mechanische Löcher. Ersatzdaten dienen nur der eigenen Statistik.',
 steps:['Betrachte zunächst die Bedeutung einzelner Leuchtereignisse. Zeichne Quelle, zwei kohärente Teilamplituden und Detektor ins Heft.','Vergleiche wenige und viele Ereignisse. Teile den Schirm gedanklich in gleich große Nachweisstreifen.','Vergleiche danach ein Modell ohne Weginformation mit vollständig unterscheidbaren Wegen. Halte Gesamtzahl und Streifenbreiten gleich.'],
 columns:[t`Schirmposition $x$ in $\mathrm{mm}$`,t`Erwartete Anzahl ohne Weginformation $N_{\mathrm k}$ in $1$`,t`Erwartete Anzahl mit Weginformation $N_{\mathrm w}$ in $1$`],
 rows:[['−4','10','20'],['−3','40','40'],['−2','10','65'],['−1','100','80'],['0','180','90'],['1','100','80'],['2','10','65'],['3','40','40'],['4','10','20']],
 note:'Didaktisch festgelegtes diskretes Verteilungsmodell mit je 500 erwarteten Nachweisen in neun gleich großen Streifen. Keine historischen Originalzählungen, keine Zufallsmessreihe und keine maßstäbliche Nachbildung des Hitachi-Aufbaus.',
 task:t`Berechne für beide Spalten die relativen Häufigkeiten beziehungsweise Modellwahrscheinlichkeiten $P_i=\frac{N_i}{500}$. Zeichne zwei Balkendiagramme. Bestimme jeweils die Wahrscheinlichkeit für den zentralen Streifen und für die drei mittleren Streifen.`,
 solution:t`Zentral ergeben sich $P=0{,}36$ ohne und $P=0{,}18$ mit Weginformation. In den drei mittleren Streifen liegen $\frac{100+180+100}{500}=0{,}76$ beziehungsweise $\frac{80+90+80}{500}=0{,}50$. Beide vollständigen Verteilungen summieren sich zu $1$.`,
 interpretation:'Einzelne reale Zählungen schwanken um Erwartungswerte. Die geänderte Verteilung bei Weginformation ist kein Effekt menschlicher Aufmerksamkeit: Entscheidend sind physikalisch unterscheidbare, mit den Wegen korrelierte Zustände.'}],
 theory:[t`Bei kohärenten, nicht unterscheidbaren Alternativen werden komplexe Wahrscheinlichkeitsamplituden addiert. Erst danach wird das Betragsquadrat gebildet. Der Interferenzterm kann die Nachweisdichte an einem Ort erhöhen oder verringern.`,t`Vollständig unterscheidbare Wegmarkierungen führen für die hier betrachtete, nicht nach der Markierung sortierte Ortsstatistik zur Summe der Einzelwahrscheinlichkeiten. Das bedeutet nicht, dass ein bewusster Beobachter die Realität herstellen müsste.`,t`Aus einem einzelnen Punkt am Schirm lässt sich das Gesamtmuster nicht ablesen. Ebenso liefert das Interferenzbild keine beobachtete klassische Flugbahn durch einen bestimmten Spalt. Die Präparation und die tatsächlich durchgeführte Messung legen fest, welche Aussagen möglich sind.`],
 formulas:[t`P(x)\propto|\psi_1(x)+\psi_2(x)|^2`,t`|\psi_1+\psi_2|^2=|\psi_1|^2+|\psi_2|^2+2\operatorname{Re}(\psi_1^*\psi_2)`],memory:'Quanten werden lokal nachgewiesen. Interferenz erscheint in der Verteilung vieler Ereignisse und setzt kohärente, nicht unterscheidbare Alternativen voraus.',
 exercises:[{title:'Grundlagen · Aus Zählungen Wahrscheinlichkeiten schätzen',task:'Von 2000 gleich präparierten Quanten werden 360 in einem festgelegten Streifen registriert. Schätze die Wahrscheinlichkeit und die erwartete Anzahl bei 500 weiteren Quanten. Muss die neue Anzahl exakt eintreten?',solution:t`Die Schätzung ist $\hat P=\frac{360}{2000}=0{,}18$. Für weitere 500 erwartet man $500\cdot0{,}18=90$ Nachweise. Die tatsächliche Anzahl kann statistisch schwanken.` ,interpretation:'Eine Wahrscheinlichkeit ist keine garantierte Ereigniszahl einer endlichen Stichprobe.'},{title:'Anwendung · Ein scheinbar widersprüchliches Gerät',task:'Ein Gerät verspricht gleichzeitig perfekte Wegerkennung und unveränderte volle Interferenz im selben, unselektierten Ensemble. Erkläre den Widerspruch zum hier behandelten Modell.',solution:'Perfekte Weginformation macht die Alternativen physikalisch unterscheidbar. In der unselektierten Ortsstatistik verschwindet dann der Interferenzterm. Nachträglich ausgewählte Teilensembles müssen getrennt betrachtet werden und erfüllen nicht dieselbe Behauptung.',interpretation:'Formuliere immer, welche Messgrößen und welche Auswahl von Ereignissen gemeinsam ausgewertet werden.'}]},
{id:'unschaerfe',title:'Unschärferelation: Ortsverteilung und Impulsverteilung',lead:'Deute Unschärfen als Streuungen eines Quantenzustands und unterscheide sie von Gerätefehlern und Spaltbreiten.',word:'und',hook:'Warum lässt sich ein eng lokalisiertes Teilchen nicht zugleich mit beliebig scharfem Impuls präparieren?',application:'Die enge räumliche Führung von Elektronen verändert ihre Impulsverteilung. Für kleine Strukturen sind diese quantenphysikalischen Grenzen relevant, auch wenn die Messgeräte ideal arbeiten.',
 experiments:[{title:'Lehrerversuch und Analogie · Beugung an einem engeren Spalt',kind:'slit',materials:'Zugelassener Schul-Laser mit Strahlführung und Schirm, einstellbarer Spalt, Maßstab. Die Lehrkraft richtet den Strahl sicher unter Augenhöhe aus; keine direkte Betrachtung des Strahls. Lichtbeugung ist hier eine anschauliche Wellenanalogie, keine direkte Messung eines Elektronen-Ortsimpulsprodukts.',
 steps:['Markiere die Mitte des Beugungsbilds und bestimme den Abstand vom Spalt zum Schirm.','Verkleinere den Spalt schrittweise. Miss jeweils den Abstand zwischen zentralem Maximum und erstem Minimum; schreibe die Werte ins Heft.','Erkläre qualitativ, wie engere räumliche Begrenzung und größere Winkelstreuung zusammenhängen. Trenne dieses Ergebnis von der präzisen Standardabweichungs-Ungleichung.'],
 columns:[t`Spaltbreite $a$ in $\mathrm{mm}$`,t`Abstand des ersten Minimums $y_1$ in $\mathrm{mm}$`],rows:[['0,100','13,00'],['0,200','6,50'],['0,400','3,25'],['0,800','1,625']],
 note:t`Berechnete Fraunhofer-Kleinwinkelwerte mit $\lambda=650\,\mathrm{nm}$ und Schirmabstand $L=2{,}00\,\mathrm m$: $y_1\approx\frac{L\lambda}{a}$. Idealer Spalt; keine real aufgenommenen Daten.`,
 task:t`Zeichne $y_1$ gegen $\frac1a$. Prüfe das Produkt $a y_1$ und beschreibe die Änderung der Winkelbreite. Begründe, warum man Spaltbreite und Abstand des ersten Minimums nicht einfach als $\sigma_x$ und $\sigma_p$ einsetzen darf.`,
 solution:t`In allen Zeilen gilt $a y_1=1{,}30\,\mathrm{mm^2}=L\lambda$. Halbiert man $a$, verdoppelt sich $y_1$. Die Größen kennzeichnen geometrische Breiten beziehungsweise ein Minimum, nicht die Standardabweichungen vollständiger Orts- und Impulsverteilungen.`,
 interpretation:'Die Beugung zeigt den Zusammenhang zwischen Lokalisation und Winkelverteilung. Eine quantitative Prüfung der Unschärferelation braucht die richtigen statistischen Größen; das ideale scharf begrenzte Spaltmodell ist dafür besonders vorsichtig zu behandeln.'}],
 theory:[t`$\sigma_x$ und $\sigma_{p_x}$ bezeichnen Standardabweichungen von Ort und derselben Impulskomponente für gleich präparierte Zustände. Die Relation $\sigma_x\sigma_{p_x}\ge\frac{\hbar}{2}$ betrifft die Präparation, nicht lediglich eine ungenaue Skala oder unvermeidliches Wackeln des Messgeräts.`,t`Ein enges Wellenpaket benötigt eine Überlagerung vieler Wellenzahlen und damit Impulse. Ein geeigneter Gaußzustand kann die untere Schranke erreichen. Für allgemeine Zustände ist das Produkt größer; aus einer großen Ortsstreuung folgt nicht automatisch ein besonders kleiner Impulsfehler.`,t`Nichtrelativistisch ist $\sigma_v=\frac{\sigma_p}{m}$. Die winzige Planck-Konstante macht die Grenze für makroskopische Gegenstände meist unbedeutend, während sie auf atomaren Skalen wesentlich ist. Energie-Zeit-Beziehungen haben eine eigene Interpretation und werden hier nicht als identisches Ort-Impuls-Messgesetz behandelt.`],
 formulas:[t`\sigma_x\sigma_{p_x}\ge\frac{\hbar}{2},\qquad\hbar=\frac h{2\pi}\approx1{,}055\cdot10^{-34}\,\mathrm{J\,s}`],memory:'Die Unschärferelation begrenzt die gleichzeitige Schärfe von Orts- und Impulsverteilungen eines Zustands. Sie ist keine bloße Aussage über schlechte Messgeräte.',
 exercises:[{title:'Grundlagen · Elektron lokalisieren',task:t`Ein Elektron wird mit $\sigma_x=0{,}10\,\mathrm{nm}$ präpariert. Bestimme die kleinste mögliche Impulsstreuung und die entsprechende Geschwindigkeitsstreuung mit $m_{\mathrm e}=9{,}109\cdot10^{-31}\,\mathrm{kg}$.`,solution:t`$\sigma_p\ge\frac{1{,}055\cdot10^{-34}}{2\cdot10^{-10}}=5{,}28\cdot10^{-25}\,\frac{\mathrm{kg\,m}}{\mathrm s}$. Damit $\sigma_v\ge5{,}79\cdot10^5\,\frac{\mathrm m}{\mathrm s}$.`,interpretation:'Die Rechnung liefert eine untere Grenze. Sie behauptet nicht, dass jeder Zustand diese Grenze erreicht.'},{title:'Anwendung · Eine Behauptung prüfen',task:t`Jemand gibt für denselben Zustand $\sigma_x=1{,}0\cdot10^{-9}\,\mathrm m$ und $\sigma_p=1{,}0\cdot10^{-27}\,\frac{\mathrm{kg\,m}}{\mathrm s}$ an. Ist dies mit der Relation vereinbar?`,solution:t`Das Produkt ist $1{,}0\cdot10^{-36}\,\mathrm{J\,s}$ und damit deutlich kleiner als $\frac{\hbar}{2}\approx5{,}28\cdot10^{-35}\,\mathrm{J\,s}$. Die Angaben sind als Standardabweichungen desselben Zustands nicht vereinbar.`,interpretation:'Vor einer Schlussfolgerung muss geklärt sein, dass dieselbe Raumrichtung und dieselbe Präparation gemeint sind.'}]},
{id:'atommodelle-spektren',title:'Atomkern, Atommodelle und das Wasserstoffspektrum',lead:'Verbinde Rutherfords Streubefund mit dem Kern-Hülle-Modell und berechne Spektrallinien aus diskreten Energien.',word:'Licht',hook:'Wie verrät Sternenlicht, welche Atome an seiner Entstehung beteiligt waren?',application:'Spektrallinien kennzeichnen mögliche Energieübergänge. Die Spektroskopie nutzt sie zur Stoffanalyse. Ein Atommodell muss zugleich erklären, warum Atome diskrete Übergänge besitzen und warum ihre positive Ladung räumlich stark konzentriert ist.',
 experiments:[{title:'Lehrerversuch · Wasserstofflinien beobachten',kind:'spectrum',materials:'Zugelassene geschlossene Wasserstoff-Spektrallampe mit gesicherter Versorgung, Schulspektrometer oder Beugungsgitter mit bekannter Kalibrierung. Bedienung der Lampe durch die Lehrkraft; alternativ Modellwerte.',
 steps:['Vergleiche zunächst das kontinuierliche Spektrum einer geeigneten Weißlichtquelle mit dem Linienspektrum.','Bestimme die Wellenlängen der sichtbaren Wasserstofflinien. Halte Kalibrierung, abgelesene Werte und Farben im Heft fest.','Ordne die Linien Übergängen auf das Niveau mit Hauptquantenzahl zwei zu. Berechne dafür die Energiedifferenzen.'],
 columns:[t`Obere Hauptquantenzahl $n$ in $1$`,t`Modellwellenlänge $\lambda$ in $\mathrm{nm}$`],rows:[['3','656,47'],['4','486,27'],['5','434,17'],['6','410,29']],
 note:t`Modellwerte aus $E_n=-\frac{13{,}6\,\mathrm{eV}}{n^2}$ und $hc=1240\,\mathrm{eV\,nm}$ für Übergänge nach $n=2$. Wegen gerundeter Konstanten keine Präzisionswerte der tatsächlichen Linien; Referenzdaten sind bei NIST verlinkt.`,
 task:t`Berechne $E_n$, $E_2$ und $\Delta E=E_n-E_2$. Zeichne ein Energieniveauschema mit Achse „Energie $E$ in $\mathrm{eV}$“. Markiere die vier Emissionsübergänge und berechne die Wellenlängen selbst.`,
 solution:t`$E_2=-3{,}40\,\mathrm{eV}$. Die Übergangsenergien betragen etwa $1{,}889;\,2{,}550;\,2{,}856;\,3{,}022\,\mathrm{eV}$. Größere Energiedifferenzen führen zu kürzeren Wellenlängen; der Übergang $3\to2$ ist die langwelligste dieser Linien.`,
 interpretation:'Das negative Vorzeichen bedeutet Bindung relativ zum gewählten Nullniveau des freien Elektrons. Die Photonenenergie ist die positive Differenz zweier Niveaus, nicht die negative Energie eines einzelnen Zustands.'},
 {title:'Historischen Befund deuten · Rutherford-Streuung',kind:'rutherford',materials:'Schematische Rekonstruktion von Strahlquelle, dünner Goldfolie und Detektor. Keine Durchführung mit offenem radioaktivem Präparat; die Auswertung nutzt normierte Modellwerte.',
 steps:['Zeichne den kollimierten Strahl und den drehbaren Detektor. Überlege, was eine überall diffus verteilte positive Ladung erwarten ließe.','Vergleiche kleine und große Streuwinkel bei identischer Detektor-Raumwinkelakzeptanz.','Formuliere im Heft, welche Aussage seltene starke Rückstreuung über Ladungskonzentration und Masse des Streuzentrums erlaubt.'],
 columns:[t`Streuwinkel $\theta$ in $\mathrm{Grad}$`,t`Normierte Zählrate $\frac{R(\theta)}{R(90^\circ)}$ in $1$`],rows:[['30','55,713'],['60','4,000'],['90','1,000'],['120','0,444'],['150','0,287']],
 note:t`Modellwerte proportional zu $\frac1{\sin^4(\theta/2)}$, auf $90^\circ$ normiert, für gleiche Raumwinkelakzeptanz. Keine historischen Zählungen. Das Coulomb-Einzelstreumodell setzt unter anderem eine dünne Folie voraus.`,
 task:'Zeichne die normierte Rate gegen den Winkel. Erkläre, warum Rückstreuung trotz geringer Häufigkeit aussagekräftig ist und warum dieses Ergebnis noch keine Elektronenbahnen festlegt.',
 solution:'Die Rate sinkt stark mit dem Winkel, verschwindet bei großen Winkeln aber nicht. Das passt zu einer stark konzentrierten positiven Ladung und nahezu der gesamten Atommasse in einem kleinen Kern. Das Streubild liefert kein vollständiges Modell der Elektronenhülle.',
 interpretation:'Die klassische Rutherford-Bahn beschreibt hier die Streuung schwerer geladener Projektile im Coulombfeld. Daraus folgt keine klassische planetenartige Elektronenbewegung in stabilen Atomen.'}],
 theory:[t`Das Kern-Hülle-Modell erklärt Rutherfords Befund: Der Kern ist gegenüber dem Atom sehr klein, positiv geladen und enthält fast die gesamte Masse. Die Elektronenhülle bestimmt viele chemische und optische Eigenschaften.`,t`Bohrs Modell ergänzt für Wasserstoff erlaubte Energien und Übergänge. Für ein isoliertes Wasserstoffatom im vereinfachten Modell gilt $E_n=-\frac{13{,}6\,\mathrm{eV}}{n^2}$. Es beschreibt wichtige Energien, aber die postulierten Kreisbahnen sind kein modernes Orbitalbild und lassen sich nicht unverändert auf Mehrelektronenatome übertragen.`,t`Bei Emission sinkt die Atomenergie und ein Photon wird ausgesandt; bei resonanter Absorption steigt sie. Die Ionisation benötigt die Energie bis zum Kontinuum. Welche Absorptionslinien auftreten, hängt auch davon ab, welche Anfangszustände tatsächlich besetzt sind.`],
 formulas:[t`E_n=-\frac{13{,}6\,\mathrm{eV}}{n^2},\qquad E_{\mathrm{Ph}}=E_{\mathrm{oben}}-E_{\mathrm{unten}}=\frac{hc}{\lambda}`],memory:'Rutherford erschließt den kleinen Atomkern, Spektren erschließen diskrete Energieunterschiede. Kein einzelnes dieser Experimente liefert eine beobachtete klassische Elektronenbahn.',
 exercises:[{title:'Grundlagen · Ein UV-Übergang',task:t`Berechne Energie und Wellenlänge des Wasserstoffübergangs $2\to1$. Liegt das Licht im sichtbaren Bereich?`,solution:t`$\Delta E=13{,}6-3{,}4=10{,}2\,\mathrm{eV}$. $\lambda=\frac{1240}{10{,}2}\,\mathrm{nm}\approx121{,}6\,\mathrm{nm}$, also im Ultraviolett.` ,interpretation:'Nicht jeder Atomübergang ist mit dem Auge sichtbar.'},{title:'Anwendung · Ionisation aus einem angeregten Zustand',task:t`Wie viel Energie braucht man mindestens, um Wasserstoff aus $n=2$ zu ionisieren? Reicht ein Photon mit $3{,}0\,\mathrm{eV}$?`,solution:t`Von $E_2=-3{,}40\,\mathrm{eV}$ bis $E=0$ fehlen $3{,}40\,\mathrm{eV}$. Ein einzelnes Photon mit $3{,}0\,\mathrm{eV}$ reicht nicht.` ,interpretation:'Die nötige Ionisationsenergie hängt vom Anfangszustand ab; der Grundzustandswert ist hier nicht einzusetzen.'}]},
{id:'franck-hertz',title:'Franck-Hertz-Versuch: Atome durch Elektronenstöße anregen',lead:'Erschließe eine Anregungsenergie aus periodischen Stromminima und unterscheide elastische von unelastischen Stößen.',word:'durch',hook:'Wie lassen sich diskrete Atomenergien nachweisen, ohne zunächst das Licht zu vermessen?',application:'Elektronen in einer Gasentladung geben Energie bei geeigneten Stößen an Atome ab. Diese Stoßanregung ist ein wichtiger Schritt in Entladungslampen und zeigt, dass nicht nur Lichtabsorption die Energiezustände eines Atoms verändert.',
 experiments:[{title:'Lehrerversuch / historische Auswertung · Franck-Hertz-Röhre',kind:'franck',materials:'Zugelassener vollständig geschlossener Schulapparat. Die Lehrkraft bedient Heizung und Versorgung nach Geräteanleitung; kein Umgang mit freiem Quecksilber. Ohne passenden Apparat werden die Ersatzdaten verwendet.',
 steps:['Skizziere Glühkathode, Beschleunigungsbereich, Gitter und Auffänger mit kleinem Gegenfeld.','Lasse den Auffängerstrom gegen die Beschleunigungsspannung aufzeichnen. Lies die Positionen mehrerer aufeinanderfolgender Minima ins Heft ab.','Bestimme Abstände benachbarter Minima und nutze zusätzlich den Abstand weit auseinanderliegender Minima für einen Mittelwert.'],
 columns:[t`Ordnungsnummer des Minimums $k$ in $1$`,t`Beschleunigungsspannung am Minimum $U_k$ in $\mathrm V$`],rows:[['1','6,20'],['2','11,10'],['3','16,00'],['4','20,90'],['5','25,80']],
 note:t`Didaktische Positionsdaten für einen idealisierten dominierenden Hg-Anregungsprozess mit $\Delta E=4{,}90\,\mathrm{eV}$ und einem frei gewählten gemeinsamen Spannungsversatz. Keine nachgemessene Originalkurve; reale Minima können verbreitert und verschoben sein.`,
 task:t`Berechne alle Spannungsabstände und $\frac{U_5-U_1}{4}$. Bestimme die Anregungsenergie und die Wellenlänge eines Photons, das bei direkter Rückkehr über dieselbe Energiedifferenz ausgesandt würde.`,
 solution:t`Alle Abstände betragen $4{,}90\,\mathrm V$. Somit $\Delta E=e\Delta U=4{,}90\,\mathrm{eV}$ und $\lambda\approx\frac{1240}{4{,}90}\,\mathrm{nm}=253\,\mathrm{nm}$. Der erste Minimalwert $6{,}20\,\mathrm V$ ist wegen des Versatzes nicht direkt die Anregungsenergie in Elektronenvolt.`,
 interpretation:'Ein Abstand ist gegenüber einem konstanten Kontaktpotential robuster als ein einzelner Spannungswert. Das Auffänger-Gegenfeld macht Elektronen sichtbar, die kurz zuvor Energie durch einen Anregungsstoß verloren haben.'}],
 theory:[t`Elektronen gewinnen im Beschleunigungsbereich kinetische Energie. Unterhalb einer passenden Anregungsenergie sind bei elastischen Stößen mit schweren Atomen nur kleine Energieüberträge möglich. Bei ausreichender Energie können unelastische Stöße diskrete Atomübergänge anregen.`,t`Nach einem solchen Stoß kann dem Elektron die Energie zum Überwinden des Gegenfeldes fehlen. Der Auffängerstrom fällt. Bei größerer Spannung sind mehrere Anregungsstöße auf dem Weg möglich, wodurch sich eine Folge von Minima ausbildet.`,t`Die ideale Periodizität beschreibt einen dominierenden Übergang; reale Atome besitzen mehrere Zustände und Prozesse. Bei Neon ist sichtbares Leuchten etwa nicht automatisch ein direkter Grundzustandsübergang über die volle Beschleunigungsenergie: Kaskaden und Zwischenzustände sind wichtig.`],
 formulas:[t`\Delta E=e\,\Delta U,\qquad \lambda=\frac{hc}{\Delta E}`],memory:'Die Abstände der Franck-Hertz-Minima weisen auf diskrete Anregungsenergien hin. Der erste Minimalwert allein kann durch Kontaktpotential und Messbedingungen verschoben sein.',
 exercises:[{title:'Grundlagen · Mehrere Minima nutzen',task:t`Zwei Minima gleicher Folge liegen bei $12{,}0\,\mathrm V$ und $26{,}7\,\mathrm V$; dazwischen liegen zwei weitere Minima. Bestimme die Anregungsenergie.` ,solution:t`Der Abstand umfasst drei Schritte. $\Delta U=\frac{26{,}7-12{,}0}{3}\,\mathrm V=4{,}90\,\mathrm V$, also $\Delta E=4{,}90\,\mathrm{eV}$.`,interpretation:'Zähle die Intervalle zwischen den Minima, nicht die Zahl ihrer Endpunkte.'},{title:'Anwendung · Eine Anregungskaskade',task:t`Ein Atom wird auf $18{,}0\,\mathrm{eV}$ über dem Grundzustand angeregt. Ein anschließender Übergang endet bei $15{,}5\,\mathrm{eV}$. Berechne die ausgesandte Photonenwellenlänge. Ist das die gesamte zuvor aufgenommene Energie?`,solution:t`Der Übergang liefert $2{,}5\,\mathrm{eV}$ und damit $\lambda=\frac{1240}{2{,}5}\,\mathrm{nm}=496\,\mathrm{nm}$. Im Atom bleiben noch $15{,}5\,\mathrm{eV}$ Anregungsenergie.` ,interpretation:'Ein sichtbares Photon kann nur einen Teil einer größeren Anregungsenergie tragen.'}]},
{id:'quantenatom',title:'Gebundene Zustände: Potentialtopf, Wellenfunktion und Orbitale',lead:'Verknüpfe Randbedingungen mit diskreten Energien und unterscheide die Wellenfunktion von ihrer Nachweisdichte.',word:'Zustände',hook:'Was bedeutet ein Orbital, wenn es keine gezeichnete Elektronenbahn ist?',application:'Orbitale beschreiben Zustände gebundener Elektronen. Der einfache eindimensionale Potentialtopf macht quantisierte Energien und räumliche Wahrscheinlichkeitsmuster verständlich und liefert eine erste Näherung für räumlich eingeschlossene Elektronen.',model:'well',
 experiments:[{title:'Analogieversuch · Randbedingungen einer gespannten Saite',kind:'well',materials:'Saite mit festen Enden und kleinem Schwingungserreger oder bestehendes Saitenmodell; daneben die unten gezeigte Quantenteilchen-Rechnung. Der Saitenversuch ist eine klassische Analogie und kein direkter Nachweis quantisierter Teilchenenergien.',
 steps:['Erzeuge auf derselben Saite Muster mit einem, zwei und drei Bäuchen. Zeichne die Knoten ins Heft.','Vergleiche mit den stationären Zuständen des unendlich hohen eindimensionalen Potentialtopfs. Markiere die beiden Randstellen, an denen die Wellenfunktion null ist.','Prüfe am Modell die Folgen einer veränderten Topfbreite. Unterscheide ausdrücklich Saitenfrequenzen und Teilchenenergien.'],
 columns:[t`Quantenzahl $n$ in $1$`,t`Teilchenenergie $E_n$ in $\mathrm{eV}$`,t`Anzahl innerer Knoten $K$ in $1$`],rows:[['1','0,376','0'],['2','1,504','1'],['3','3,384','2'],['4','6,016','3']],
 note:t`Berechnete nichtrelativistische Elektronenwerte für den unendlich hohen Potentialtopf der Breite $L=1{,}00\,\mathrm{nm}$ mit $E_1=0{,}376\,\mathrm{eV}$. Keine Energiedaten einer Saite oder eines Wasserstoffatoms.`,
 task:t`Zeichne $E_n$ gegen $n^2$. Skizziere für $n=1$ und $n=2$ jeweils $\psi$ sowie $|\psi|^2$ getrennt. Bestimme Energie und inneren Knotenabstand für $n=3$.`,
 solution:t`Die Steigung beträgt $0{,}376\,\mathrm{eV}$. Für $n=3$ gilt $E_3=3{,}384\,\mathrm{eV}$; die inneren Knoten liegen bei $\frac L3$ und $\frac{2L}3$, also etwa $0{,}333\,\mathrm{nm}$ auseinander. Das Betragsquadrat ist auch dort positiv, wo $\psi$ negativ ist; an Knoten bleibt es null.`,
 interpretation:'Die Quantenzahl beginnt bei eins: Der Zustand mit überall verschwindender Wellenfunktion beschreibt kein vorhandenes Teilchen. Bei einer klassischen Saite sind die Eigenfrequenzen diskret, die Schwingungsenergie ist jedoch nicht allein dadurch in denselben Quanten festgelegt.'}],
 theory:[t`Die Wellenfunktion $\psi$ ist eine Zustandsbeschreibung, keine unmittelbar gemessene Stoffdichte. Für ein Teilchen in einer Raumdimension ist $\rho(x)=|\psi(x)|^2$ eine Wahrscheinlichkeitsdichte mit der Einheit $\mathrm{m^{-1}}$; Wahrscheinlichkeiten erhält man durch Integration über Intervalle.`,t`Im unendlich hohen Topf gilt $\psi(0)=\psi(L)=0$. Erlaubt sind $\psi_n(x)=\sqrt{\frac2L}\sin\!\left(\frac{n\pi x}{L}\right)$ und $E_n=\frac{n^2h^2}{8mL^2}$. Der Grundzustand besitzt eine von null verschiedene Energie. Bei endlichen Barrieren können Zustände in den verbotenen Bereich hineinreichen; das unendliche Modell beschreibt diesen Tunneleffekt nicht.`,t`Im Atom ersetzt ein dreidimensionales Coulombpotential die rechteckigen Wände. Atomorbitale sind stationäre räumliche Zustände, keine Kreisbahnen. Quantenzahlen kennzeichnen Energie- und Drehimpulseigenschaften; beim Wasserstoff hängt die einfache Energieformel vor allem von $n$ ab.`,t`Elektronen besitzen zusätzlich Spin. Das Pauli-Prinzip erlaubt in einem räumlichen Orbital höchstens zwei Elektronen mit entgegengesetzten Spinprojektionen. Mehrere Elektronen beeinflussen einander; dadurch unterscheidet sich die Energiefolge von der einfachen Wasserstoffformel.`],
 formulas:[t`P(a\le x\le b)=\int_a^b|\psi(x)|^2\,\mathrm dx`,t`E_n=\frac{n^2h^2}{8mL^2},\qquad n=1,2,3,\ldots`],memory:'Ein Orbital ist ein Quantenzustand mit räumlicher Nachweisdichte. Randbedingungen begrenzen die erlaubten Zustände; die Wellenfunktion selbst ist keine Teilchenbahn.',
 exercises:[{title:'Grundlagen · Kleineren Raum untersuchen',task:t`Ein Elektron hat im Topf mit $L=1{,}00\,\mathrm{nm}$ die Grundzustandsenergie $0{,}376\,\mathrm{eV}$. Wie groß wird sie bei $L=0{,}50\,\mathrm{nm}$?`,solution:t`Wegen $E_1\propto L^{-2}$ vervierfacht sie sich auf $1{,}504\,\mathrm{eV}$.`,interpretation:'Räumliche Einengung erhöht im Modell die kleinste mögliche kinetische Energie.'},{title:'Anwendung · Ein Übergang und ein Ortsnachweis',task:t`Im Topf mit $L=1{,}00\,\mathrm{nm}$ fällt ein Elektron von $n=2$ nach $n=1$. Berechne die Photonenwellenlänge unter der Annahme eines möglichen Strahlungsübergangs. Ist im Zustand $n=2$ ein Nachweis exakt in der Mitte wahrscheinlich?`,solution:t`$\Delta E=1{,}504-0{,}376=1{,}128\,\mathrm{eV}$, daher $\lambda\approx1099\,\mathrm{nm}$. In der Mitte ist $\psi_2=0$, also auch die Dichte null. Ein endliches Messintervall um die Mitte hat dennoch im Allgemeinen eine kleine positive Wahrscheinlichkeit.` ,interpretation:'Dichte an einem Punkt und Wahrscheinlichkeit eines endlichen Messintervalls sind unterschiedliche Größen.'}]},
{id:'halbleiter',title:'Festkörper, Halbleiter und LEDs',lead:'Erkläre Bänder, Dotierung und den p-n-Übergang und verknüpfe die LED-Farbe mit einer Energiedifferenz.',word:'und',hook:'Warum macht ein Halbleitermaterial aus elektrischem Strom farbiges Licht?',application:'LEDs nutzen die Rekombination von Ladungsträgern in geeigneten Halbleitern. Die Materialstruktur bestimmt die möglichen Übergänge und damit die Farbe; eine Solarzelle nutzt umgekehrt absorbiertes Licht zur Erzeugung und Trennung von Ladungsträgern.',
 experiments:[{title:'Schülerversuch · LED-Farbe und Vorwärtsspannung',kind:'led',materials:'Rote, gelbe, grüne und blaue LED, strombegrenzte sichere Kleinspannungsquelle, geeigneter Vorwiderstand, Strom- und Spannungsmessgerät sowie Schulspektrometer. Zulässige LED-Ströme einhalten; Anschlüsse bei ausgeschalteter Quelle ändern.',
 steps:['Skizziere eine Reihenschaltung aus Quelle, Schutzwiderstand, Strommesser und LED. Miss die LED-Spannung parallel zur LED.','Stelle für jede LED denselben kleinen Strom ein und bestimme die Wellenlänge des Emissionsmaximums. Halte Farben und Werte im Heft fest.','Berechne die Photonenenergie. Vergleiche sie kritisch mit der elektrischen Energie pro Elementarladung über der LED.'],
 columns:['LED-Farbe',t`Wellenlänge am Maximum $\lambda_{\max}$ in $\mathrm{nm}$`,t`LED-Stromstärke $I$ in $\mathrm{mA}$`,t`Vorwärtsspannung $U_{\mathrm F}$ in $\mathrm V$`],
 rows:[['rot','620','5,0','1,90'],['gelb','590','5,0','2,00'],['grün','525','5,0','2,80'],['blau','470','5,0','3,00']],
 note:'Plausibel gewählte didaktische Anzeigen verschiedener LEDs, keine Kennwerte konkreter Bauteile und keine präzise Bestimmung der Planck-Konstante. Wellenlänge, Vorwärtsspannung, Strom und Temperatur sind in realen Geräten material- und betriebsabhängig.',
 task:t`Berechne im Heft $E_{\mathrm{Ph}}=\frac{hc}{\lambda_{\max}}$ in $\mathrm{eV}$. Zeichne Photonenenergie gegen $\frac1{\lambda_{\max}}$ und vergleiche zusätzlich mit $eU_{\mathrm F}$. Begründe, weshalb nicht für jedes Bauteil exakt $eU_{\mathrm F}=E_{\mathrm{Ph}}$ gelten muss.`,
 solution:t`Die Photonenenergien betragen etwa $2{,}00;\,2{,}10;\,2{,}36;\,2{,}64\,\mathrm{eV}$. Sie steigen mit dem Kehrwert der Wellenlänge. Die angegebenen Vorwärtsspannungen stimmen nicht exakt mit diesen Zahlenwerten überein; die Diodenkennlinie ist kein ideales direktes Photonen-Energiemessgerät.`,
 interpretation:'Ladungsträgerverteilungen, Kontakte, Widerstände, Temperatur und nichtstrahlende Prozesse spielen mit. Die Photonenenergie orientiert sich bei einer geeigneten LED an der Übergangsenergie nahe der Bandlücke; eine frei gewählte Einschalt-Schwelle ist kein zuverlässiges Naturkonstantenexperiment.'}],
 theory:[t`In einem Festkörper führen viele wechselwirkende Atome zu Energiebändern. Zwischen Valenz- und Leitungsband kann eine verbotene Energielücke liegen. Elektronen im Leitungsband und Löcher im Valenzband tragen zum Strom bei. Ein Loch ist ein fehlendes Elektron in einem sonst weitgehend besetzten Band, kein freies positives Proton.`,t`Donatoren erleichtern die Bereitstellung von Elektronen, Akzeptoren erzeugen bewegliche Löcher. Ein dotierter Halbleiter bleibt insgesamt nahezu elektrisch neutral. Am p-n-Übergang entsteht durch Diffusion und zurückbleibende feste Ionen eine Raumladungszone mit innerem Feld.`,t`In Durchlassrichtung kann Ladungsträgerinjektion die Rekombination ermöglichen. Geeignete direkte Bandübergänge erzeugen Photonen; andere Prozesse geben Energie an das Gitter ab. Silizium ist wegen seiner indirekten Bandlücke kein effizienter gewöhnlicher sichtbarer LED-Werkstoff.`,t`Bei einer Solarzelle kann Licht mit ausreichender Photonenenergie Elektron-Loch-Paare erzeugen. Das innere Feld und die Kontakte ermöglichen eine gerichtete Ladungsträgertrennung und elektrische Energieabgabe. Nicht jede absorbierte Photonenenergie wird als nutzbare elektrische Arbeit abgegeben.`],
 formulas:[t`E_{\mathrm{Ph}}=\frac{hc}{\lambda}\approx E_{\mathrm g}\quad\text{für geeignete strahlende Bandübergänge}`],memory:'Halbleitertechnik nutzt erlaubte Bänder, Bandlücken und Ladungsträger. LED-Farbe und Vorwärtsspannung hängen zusammen, sind aber nicht durch eine universelle exakte Gleichheit austauschbar.',
 exercises:[{title:'Grundlagen · Eine Farbe abschätzen',task:t`Ein idealisierter strahlender Übergang hat $\Delta E=2{,}48\,\mathrm{eV}$. Berechne die Wellenlänge. Welcher Übergang ist energiereicher: dieser oder einer mit $\lambda=620\,\mathrm{nm}$?`,solution:t`$\lambda=\frac{1240}{2{,}48}\,\mathrm{nm}=500\,\mathrm{nm}$. Der Übergang bei $620\,\mathrm{nm}$ hat nur $2{,}00\,\mathrm{eV}$ und ist energieärmer.` ,interpretation:'Kürzere Wellenlänge bedeutet größere Energie pro Photon, nicht automatisch größere gesamte Lichtleistung.'},{title:'Anwendung · Strom begrenzen',task:t`Eine LED soll bei $U_{\mathrm F}=2{,}0\,\mathrm V$ an einer $5{,}0\,\mathrm V$-Quelle mit $I=5{,}0\,\mathrm{mA}$ betrieben werden. Berechne den erforderlichen idealisierten Vorwiderstand und seine Verlustleistung.` ,solution:t`$R=\frac{5{,}0-2{,}0}{0{,}0050}\,\Omega=600\,\Omega$. $P_R=I^2R=0{,}015\,\mathrm W$. Ein realer Widerstand wird nach verfügbaren Werten und ausreichender Belastbarkeit gewählt.` ,interpretation:'Die LED wird nicht direkt an eine ungeregelte Spannungsquelle gelegt; ihre steile Kennlinie erfordert Strombegrenzung.'}]},
{id:'atomkerne',title:'Atomkerne: Radioaktivität, Halbwertszeit und Bindungsenergie',lead:'Unterscheide Kernumwandlungen von Hüllenübergängen, bestimme eine Halbwertszeit und bilanziere Energie über die Massendifferenz.',word:'Wahrscheinlichkeiten.',hook:'Warum ist der Zerfall eines einzelnen Kerns zufällig, die Abnahme vieler Kerne aber berechenbar?',application:'Radioaktive Tracer, Altersbestimmung und Kernenergiebilanzen nutzen verschiedene Eigenschaften von Atomkernen. Für ihre Beurteilung musst du Aktivität, statistischen Zerfall und frei werdende Energie auseinanderhalten.',
 experiments:[{title:'Lehrerversuch / Datenauswertung · Eine Zerfallsrate',kind:'decay',materials:'Vorhandenes zugelassenes Schul-Zählgerät und gegebenenfalls ein dafür vorgesehenes geschlossenes Demonstrationssystem, ausschließlich durch die befugte Lehrkraft. Ohne geeigneten Aufbau werden die Ersatzdaten genutzt; keine Beschaffung oder Bearbeitung radioaktiver Stoffe.',
 steps:['Bestimme zunächst den Untergrund ohne untersuchte Quelle bei derselben Messzeit. Notiere die Messgeometrie.','Erfasse gleiche kurze Zeitfenster in regelmäßigen Zeitabständen. Halte Abstand und Detektoreinstellungen fest; protokolliere Zählwerte ausschließlich im Heft.','Ziehe die mittlere Untergrundrate ab. Suche nicht die Hälfte der Bruttorate, sondern die Hälfte der korrigierten Rate.'],
 columns:[t`Zeit $t$ in $\mathrm{min}$`,t`Bruttozählrate $R_{\mathrm b}$ in $\mathrm{s^{-1}}$`,t`Untergrundzählrate $R_0$ in $\mathrm{s^{-1}}$`],
 rows:[['0','84,0','4,0'],['2','44,0','4,0'],['4','24,0','4,0'],['6','14,0','4,0'],['8','9,0','4,0']],
 note:t`Erwartungswerte eines hypothetischen Zerfallsmodells mit $T_{1/2}=2{,}0\,\mathrm{min}$ und konstantem Untergrund. Kein reales Isotop wird behauptet; statistische Schwankungen und Totzeit fehlen. Die Zeitfenster seien kurz gegenüber der Halbwertszeit.`,
 task:t`Berechne die Nettozählrate $R=R_{\mathrm b}-R_0$ und zeichne sie gegen $t$. Bestimme $T_{1/2}$ und die Zerfallskonstante $\lambda_{\mathrm Z}$ in $\mathrm{s^{-1}}$. Begründe, warum die Zählrate ohne Wirkungsgrad und Geometrie noch nicht die Aktivität ist.`,
 solution:t`Netto ergeben sich $80;\,40;\,20;\,10;\,5\,\mathrm{s^{-1}}$. Die Halbwertszeit ist $2{,}0\,\mathrm{min}=120\,\mathrm s$. $\lambda_{\mathrm Z}=\frac{\ln2}{120\,\mathrm s}\approx5{,}78\cdot10^{-3}\,\mathrm{s^{-1}}$. Der Detektor registriert meist nur einen Teil der Zerfälle.`,
 interpretation:'Ein einzelner Kern hat keine feste ablaufende Zerfallsuhr. Die Exponentialfunktion beschreibt Erwartungswerte eines Ensembles. Die Aktivität in Becquerel zählt Zerfälle pro Sekunde, eine Anzeige in Zählungen pro Sekunde hängt zusätzlich vom Messaufbau ab.'},
 {title:'Massenmessungen auswerten · Bindung des Heliumkerns',kind:'nucleus',materials:'Rechen- und Modellversuch mit gerundeten neutralen Atommassen und Neutronenmasse. Die präzise Massenbestimmung ist ein Forschungsexperiment, kein Arbeitsschritt mit Kernreaktionen im Klassenzimmer.',
 steps:['Notiere im Heft die Zusammensetzung eines Helium-4-Kerns.','Verwende bei der Massenbilanz entweder konsequent Kernmassen oder konsequent passende neutrale Atommassen. Hier werden zwei Wasserstoffatome und zwei Neutronen mit einem Heliumatom verglichen.','Bestimme Massendefekt, Bindungsenergie und Bindungsenergie pro Nukleon.'],
 columns:['Teilchen / Atom',t`Masse $m$ in $\mathrm u$`],rows:[['Wasserstoff-1-Atom','1,007825'],['Neutron','1,008665'],['Helium-4-Atom','4,002603']],
 note:t`Gerundete Referenzgrößen als didaktischer Rechendatensatz; keine im Unterricht gemessenen Massen. Für diese Genauigkeit wird die kleine Differenz der elektronischen Bindungsenergien vernachlässigt. Verwende $1\,\mathrm u\,c^2=931{,}494\,\mathrm{MeV}$.`,
 task:t`Berechne $\Delta m=2m_{\mathrm H}+2m_{\mathrm n}-m_{\mathrm{He}}$. Erkläre, weshalb die Elektronenmassen in dieser Bilanz weitgehend herausfallen, und bestimme $E_{\mathrm B}$ sowie $\frac{E_{\mathrm B}}4$.`,
 solution:t`$\Delta m=0{,}030377\,\mathrm u$. Daher $E_{\mathrm B}\approx28{,}30\,\mathrm{MeV}$ und $\frac{E_{\mathrm B}}4\approx7{,}07\,\mathrm{MeV}$ pro Nukleon. Auf beiden Seiten sind insgesamt zwei Elektronen in den verwendeten Atommassen enthalten.`,
 interpretation:'Bindungsenergie ist die Energie, die zum vollständigen Zerlegen in freie Bestandteile nötig wäre. Ein größerer Bindungsenergiebetrag entspricht bei gleicher Zusammensetzung einer kleineren Gesamtmasse des gebundenen Systems.'}],
 theory:[t`Ein Kern enthält $Z$ Protonen und $N$ Neutronen; seine Massenzahl ist $A=Z+N$. Isotope haben gleiches $Z$, aber verschiedenes $N$. Kernenergien liegen häufig im $\mathrm{MeV}$-Bereich und unterscheiden sich dadurch stark von vielen Hüllenübergängen im $\mathrm{eV}$-Bereich.`,t`Beim Alphazerfall wird ein Helium-4-Kern ausgesandt. Beim $\beta^-$-Zerfall wird im Kern ein Neutron in ein Proton umgewandelt; Elektron und Antineutrino werden erzeugt und ausgesandt. Gammastrahlung entsteht bei einem Energieübergang des Kerns und ändert allein weder $A$ noch $Z$.`,t`Für ein einzelnes Nuklid ohne Nachproduktion und bei konstanter Zerfallswahrscheinlichkeit gilt im Erwartungswert $N(t)=N_0e^{-\lambda_{\mathrm Z}t}$ und $\mathcal A(t)=\lambda_{\mathrm Z}N(t)$. Gemessene Zählungen schwanken; bei unabhängigen Ereignissen ist die Standardabweichung einer Poisson-Zählung ungefähr $\sqrt n$.`,t`Massendifferenzen entsprechen Energiedifferenzen. Bei Spaltung schwerer oder Fusion geeigneter leichter Kerne kann die Bindung pro Nukleon im Produkt größer sein. Ob eine konkrete Reaktion Energie freisetzt, entscheidet die vollständige Massenbilanz; Reaktionsraten und nötige Startbedingungen sind davon zu unterscheiden.`],
 formulas:[t`T_{1/2}=\frac{\ln2}{\lambda_{\mathrm Z}},\qquad \mathcal A=\lambda_{\mathrm Z}N`,t`E_{\mathrm B}=\Delta m\,c^2,\qquad Q=(m_{\mathrm{vor}}-m_{\mathrm{nach}})c^2`],memory:'Zerfall ist für einzelne Kerne zufällig und für große Ensembles statistisch beschreibbar. Bei Kernprozessen bleibt Energie erhalten; Unterschiede der Gesamtmassen gehören in die Energiebilanz.',
 exercises:[{title:'Grundlagen · Halbwertszeiten zählen',task:t`Eine Probe enthält anfangs $8{,}0\cdot10^6$ Kerne eines Nuklids mit $T_{1/2}=3{,}0\,\mathrm h$. Wie viele sind nach $9{,}0\,\mathrm h$ im Erwartungswert noch nicht zerfallen? Wie groß ist die Anfangsaktivität?`,solution:t`Drei Halbwertszeiten lassen $\frac18$ übrig: $N=1{,}0\cdot10^6$. $\mathcal A_0=\frac{\ln2}{10800\,\mathrm s}\cdot8{,}0\cdot10^6\approx513\,\mathrm{Bq}$.`,interpretation:'Becquerel gibt eine Zerfallsrate an, keine gespeicherte Energie und keine Dosis.'},{title:'Anwendung · Energie einer Reaktion',task:t`Die Gesamtmasse der Produkte einer vollständig bilanzierten Reaktion ist um $0{,}0200\,\mathrm u$ kleiner als die Ausgangsmasse. Bestimme die frei werdende Energie. Welche Zahlen ändern sich bei einem $\beta^-$-Zerfall des Kerns?`,solution:t`$Q=0{,}0200\cdot931{,}494\,\mathrm{MeV}=18{,}63\,\mathrm{MeV}$. Beim $\beta^-$-Zerfall bleibt $A$ gleich, $Z$ wächst um eins und die Neutronenzahl sinkt um eins.` ,interpretation:'Die Reaktionsenergie allein sagt nicht, mit welcher Wahrscheinlichkeit oder Geschwindigkeit der Prozess stattfindet.'}]}
];
